<?php
namespace App\Controllers;
use App\Core\Database;
final class AdminController{
 public function dashboard():void{$db=Database::db();$sales=(int)$db->query("SELECT COALESCE(SUM(total),0) FROM orders WHERE status='paid'")->fetchColumn();$orders=(int)$db->query("SELECT COUNT(*) FROM orders WHERE status='paid'")->fetchColumn();$stats=['sales'=>$sales,'orders'=>$orders,'pending'=>(int)$db->query("SELECT COUNT(*) FROM orders WHERE status='pending'")->fetchColumn(),'sold'=>(int)$db->query("SELECT COUNT(*) FROM order_items i JOIN orders o ON o.id=i.order_id WHERE o.status='paid'")->fetchColumn(),'photos'=>(int)$db->query('SELECT COUNT(*) FROM photos')->fetchColumn(),'storage'=>(int)$db->query('SELECT COALESCE(SUM(file_size),0) FROM photos')->fetchColumn(),'average'=>$orders?(int)round($sales/$orders):0];$daily=$db->query("SELECT DATE(paid_at) day,SUM(total) total FROM orders WHERE paid_at>=DATE_SUB(CURDATE(),INTERVAL 13 DAY) AND status='paid' GROUP BY DATE(paid_at) ORDER BY day")->fetchAll();$topEvents=$db->query("SELECT e.name,e.sport,e.event_date,COALESCE(SUM(i.unit_price),0) sales,COUNT(DISTINCT o.id) orders_count,MIN(p.preview_path) preview_path FROM events e JOIN photos p ON p.event_id=e.id LEFT JOIN order_items i ON i.photo_id=p.id LEFT JOIN orders o ON o.id=i.order_id AND o.status='paid' GROUP BY e.id ORDER BY sales DESC LIMIT 3")->fetchAll();$recent=$db->query("SELECT o.*,COUNT(i.id) items FROM orders o LEFT JOIN order_items i ON i.order_id=o.id GROUP BY o.id ORDER BY o.id DESC LIMIT 6")->fetchAll();admin_view('admin/dashboard',['stats'=>$stats,'daily'=>$daily,'topEvents'=>$topEvents,'recent'=>$recent,'pageTitle'=>'Resumen','adminSection'=>'dashboard']);}
 public function photos():void{$db=Database::db();$events=$db->query('SELECT * FROM events ORDER BY event_date DESC')->fetchAll();$photos=$db->query('SELECT p.*,e.name event_name FROM photos p JOIN events e ON e.id=p.event_id ORDER BY p.id DESC LIMIT 100')->fetchAll();admin_view('admin/photos',['events'=>$events,'photos'=>$photos,'pageTitle'=>'Subir fotografías','adminSection'=>'photos']);}
 public function upload():never{verify_csrf();$event=(int)($_POST['event_id']??0);$watermark=isset($_POST['watermark']);$files=$_FILES['photos']??null;if(!$event||!$files){$_SESSION['error']='Selecciona un evento y al menos una fotografía.';redirect('/admin/fotos');}$dirs=[ROOT.'/storage/originals',ROOT.'/storage/previews'];foreach($dirs as $dir){if(!is_dir($dir)&&!@mkdir($dir,0775,true)){$_SESSION['error']='No fue posible crear la carpeta: '.$dir;redirect('/admin/fotos');}@chmod($dir,0775);if(!is_writable($dir)){$_SESSION['error']='La carpeta storage no tiene permisos de escritura.';redirect('/admin/fotos');}}$uploaded=0;$failed=[];foreach($files['tmp_name'] as $k=>$tmp){$name=$files['name'][$k]??'archivo';if(($files['error'][$k]??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK){$failed[]=$name.' (error de carga)';continue;}if(!is_uploaded_file($tmp)||!@getimagesize($tmp)){$failed[]=$name.' (imagen inválida)';continue;}$ext=strtolower(pathinfo($name,PATHINFO_EXTENSION));if(!in_array($ext,['jpg','jpeg','png','webp'],true)){$failed[]=$name.' (formato no permitido)';continue;}$token=bin2hex(random_bytes(10));$orig='storage/originals/'.$token.'.'.$ext;$preview='storage/previews/'.$token.'.jpg';$origAbs=ROOT.'/'.$orig;$previewAbs=ROOT.'/'.$preview;if(!@move_uploaded_file($tmp,$origAbs)||!is_file($origAbs)){$failed[]=$name.' (sin permiso para guardar)';continue;}if(!$this->preview($origAbs,$previewAbs,$watermark)){@unlink($origAbs);$failed[]=$name.' (no se pudo generar la vista previa)';continue;}$size=(int)@filesize($origAbs);$s=Database::db()->prepare("INSERT INTO photos(event_id,title,bib_number,price,original_path,preview_path,file_size,watermark_enabled,download_enabled,status) VALUES(?,?,?,?,?,?,?,?,?,'active')");$s->execute([$event,pathinfo($name,PATHINFO_FILENAME),trim($_POST['bib_number']??''),max(0,(int)($_POST['price']??4990)),$orig,$preview,$size,$watermark?1:0,isset($_POST['download_enabled'])?1:0]);$uploaded++;}if($uploaded)$_SESSION['success']=$uploaded.' fotografía(s) publicada(s) correctamente.';if($failed)$_SESSION['error']='No se procesaron: '.implode(', ',$failed);redirect('/admin/fotos');}
 public function toggleDownload():never{verify_csrf();[$id,$enabled]=array_pad(explode(':',$_POST['toggle']??'0:0'),2,0);$s=Database::db()->prepare('UPDATE photos SET download_enabled=? WHERE id=?');$s->execute([(int)$enabled,(int)$id]);redirect('/admin/fotos');}
 public function editPhoto():void{$db=Database::db();$s=$db->prepare('SELECT p.*,e.name event_name FROM photos p JOIN events e ON e.id=p.event_id WHERE p.id=?');$s->execute([(int)($_GET['id']??0)]);$photo=$s->fetch();if(!$photo){http_response_code(404);exit('Fotografía no encontrada');}$events=$db->query('SELECT * FROM events ORDER BY event_date DESC')->fetchAll();admin_view('admin/photo-edit',['photo'=>$photo,'events'=>$events,'pageTitle'=>'Editar fotografía','adminSection'=>'photos']);}
 public function updatePhoto():never{verify_csrf();$status=in_array($_POST['status']??'',['active','hidden'],true)?$_POST['status']:'active';$s=Database::db()->prepare('UPDATE photos SET event_id=?,title=?,bib_number=?,price=?,watermark_enabled=?,download_enabled=?,status=? WHERE id=?');$s->execute([(int)$_POST['event_id'],trim($_POST['title']??''),trim($_POST['bib_number']??''),max(0,(int)$_POST['price']),isset($_POST['watermark_enabled'])?1:0,isset($_POST['download_enabled'])?1:0,$status,(int)$_POST['id']]);$_SESSION['success']='Fotografía actualizada.';redirect('/admin/fotos');}
 public function togglePhotoStatus():never{verify_csrf();$status=($_POST['status']??'')==='active'?'active':'hidden';Database::db()->prepare('UPDATE photos SET status=? WHERE id=?')->execute([$status,(int)$_POST['id']]);$_SESSION['success']=$status==='active'?'Fotografía habilitada.':'Fotografía deshabilitada.';redirect('/admin/fotos');}
 public function deletePhoto():never{verify_csrf();$db=Database::db();$id=(int)$_POST['id'];$sold=$db->prepare('SELECT COUNT(*) FROM order_items WHERE photo_id=?');$sold->execute([$id]);if((int)$sold->fetchColumn()>0){$db->prepare("UPDATE photos SET status='hidden' WHERE id=?")->execute([$id]);$_SESSION['success']='La fotografía posee ventas asociadas y fue deshabilitada para conservar el historial.';redirect('/admin/fotos');}$s=$db->prepare('SELECT original_path,preview_path FROM photos WHERE id=?');$s->execute([$id]);$photo=$s->fetch();if($photo){foreach(['original_path','preview_path'] as $key){$candidate=ROOT.'/'.ltrim($photo[$key],'/');$storage=realpath(ROOT.'/storage');$parent=realpath(dirname($candidate));if($storage&&$parent&&str_starts_with($parent,$storage)&&is_file($candidate))unlink($candidate);}$db->prepare('DELETE FROM photos WHERE id=?')->execute([$id]);$_SESSION['success']='Fotografía eliminada definitivamente.';}redirect('/admin/fotos');}
 private function preview(string $src,string $dest,bool $wm):bool{$info=@getimagesize($src);if(!$info||!function_exists('imagecreatetruecolor'))return false;$create=match($info[2]){IMAGETYPE_JPEG=>'imagecreatefromjpeg',IMAGETYPE_PNG=>'imagecreatefrompng',IMAGETYPE_WEBP=>'imagecreatefromwebp',default=>null};if(!$create||!function_exists($create))return false;$im=@$create($src);if(!$im)return false;$w=imagesx($im);$h=imagesy($im);if($w<1||$h<1){imagedestroy($im);return false;}$nw=min($w,1600);$nh=max(1,(int)round($h*$nw/$w));$out=imagecreatetruecolor($nw,$nh);$bg=imagecolorallocate($out,255,255,255);imagefill($out,0,0,$bg);imagecopyresampled($out,$im,0,0,0,0,$nw,$nh,$w,$h);if($wm){$white=imagecolorallocatealpha($out,255,255,255,55);for($y=120;$y<$nh;$y+=260)for($x=-100;$x<$nw;$x+=440)imagestring($out,5,$x,$y,'ULTRA MEDIA DIGITAL',$white);}$saved=@imagejpeg($out,$dest,82);imagedestroy($im);imagedestroy($out);return $saved&&is_file($dest);}
}
